const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "kvhttp", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    run.step.dependOn(b.getInstallStep());
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Connection handling: one concurrent task per accepted connection, one
//! request per connection, each bounded by I/O deadlines.

const Server = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;
const net = Io.net;
const log = std.log.scoped(.server);

const http = @import("http.zig");
const routes = @import("routes.zig");
const Store = @import("Store.zig");

io: Io,
gpa: Allocator,
store: *Store,
options: Options,

pub const Options = struct {
    /// Overall budget for receiving the request and sending the response.
    io_timeout: Io.Duration = .fromSeconds(30),
    /// Lingering-close budget for draining unread input after the response.
    drain_timeout: Io.Duration = .fromSeconds(2),
    /// Largest accepted request head, including the terminating blank line.
    max_head_len: usize = 64 * 1024,
    /// Size of the per-connection send buffer.
    write_buffer_len: usize = 8 * 1024,
};

/// Accepts connections until the listener fails or the task is canceled.
pub fn serve(server: *Server, listener: *net.Server) net.Server.AcceptError!void {
    const io = server.io;
    var group: Io.Group = .init;
    defer group.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.ConnectionAborted => continue,
            error.ProcessFdQuotaExceeded,
            error.SystemFdQuotaExceeded,
            error.SystemResources,
            => {
                // Back off briefly so in-flight connections can finish and free resources.
                log.warn("accept: {t}", .{err});
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => |e| return e,
        };
        setNoDelay(stream);
        group.concurrent(io, serveConnection, .{ server, stream }) catch |err| {
            log.warn("dropping connection: {t}", .{err});
            stream.close(io);
        };
    }
}

fn setNoDelay(stream: net.Stream) void {
    const posix = std.posix;
    const one: c_int = 1;
    posix.setsockopt(stream.socket.handle, posix.IPPROTO.TCP, posix.TCP.NODELAY, std.mem.asBytes(&one)) catch {};
}

/// Supervises one connection: runs it as a separate task and cancels that
/// task if it misses its deadline. Cancelation interrupts blocking reads and
/// writes, which a shutdown(2) from another thread does not do on every OS.
fn serveConnection(server: *Server, stream: net.Stream) void {
    const io = server.io;
    defer stream.close(io);

    var conn: Connection = .{ .server = server, .stream = stream };
    var task = io.concurrent(Connection.run, .{&conn}) catch |err| {
        log.warn("dropping connection: {t}", .{err});
        return;
    };

    const phases = [_]struct { *Io.Event, Io.Duration }{
        .{ &conn.responded, server.options.io_timeout },
        .{ &conn.finished, server.options.drain_timeout },
    };
    for (phases) |phase| {
        const event, const timeout = phase;
        event.waitTimeout(io, .{ .duration = .{ .raw = timeout, .clock = .awake } }) catch |err| {
            log.debug("connection {s}", .{if (err == error.Timeout) "timed out" else "canceled"});
            return task.cancel(io);
        };
    }
    task.await(io);
}

const Connection = struct {
    server: *Server,
    stream: net.Stream,
    /// Set once the response is sent or the exchange has failed.
    responded: Io.Event = .unset,
    /// Set when the connection task is about to return.
    finished: Io.Event = .unset,

    fn run(conn: *Connection) void {
        const server = conn.server;
        const io = server.io;
        defer {
            conn.responded.set(io);
            conn.finished.set(io);
        }

        var arena_state: std.heap.ArenaAllocator = .init(server.gpa);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        const read_buffer = arena.alloc(u8, server.options.max_head_len) catch return;
        const write_buffer = arena.alloc(u8, server.options.write_buffer_len) catch return;
        var reader = conn.stream.reader(io, read_buffer);
        var writer = conn.stream.writer(io, write_buffer);

        server.exchange(arena, &reader.interface, &writer.interface) catch |err| {
            log.debug("connection dropped: {t}", .{err});
            return;
        };
        conn.responded.set(io);

        // Half-close and drain so that unread request bytes do not trigger a
        // RST that could discard the response before the client reads it.
        conn.stream.shutdown(io, .send) catch return;
        _ = reader.interface.discardRemaining() catch {};
    }
};

const ExchangeError = error{ ReadFailed, EndOfStream, WriteFailed };

/// Reads one request and writes its response.
fn exchange(server: *Server, arena: Allocator, r: *Io.Reader, w: *Io.Writer) ExchangeError!void {
    const res = try server.readAndHandle(arena, r, w);
    try http.writeResponse(w, res.status, res.content_type, res.body);
    try w.flush();
}

fn readAndHandle(server: *Server, arena: Allocator, r: *Io.Reader, w: *Io.Writer) ExchangeError!routes.Response {
    const head_len = while (true) {
        if (http.headLength(r.buffered())) |n| break n;
        if (r.bufferedLen() >= server.options.max_head_len)
            return .empty(.request_header_fields_too_large);
        try r.fillMore();
    };

    // Copy the head out of the read buffer, which reading the body may reuse.
    const head = arena.dupe(u8, r.buffered()[0..head_len]) catch
        return .empty(.internal_server_error);
    r.toss(head_len);

    const req = http.parseHead(head) catch |err| return .empty(http.statusForError(err));
    if (req.content_length > routes.max_value_len) return .empty(.content_too_large);

    const body = arena.alloc(u8, req.content_length) catch return .empty(.internal_server_error);
    if (req.expect_continue and r.bufferedLen() < body.len) {
        try w.writeAll(http.continue_line);
        try w.flush();
    }
    try r.readSliceAll(body);

    return routes.handle(server.store, server.io, arena, req, body);
}

//! Thread-safe in-memory key-value store. Keys and values are owned copies.

const Store = @This();

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub const PutResult = enum { created, replaced };

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *Store) void {
    var it = store.map.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        store.gpa.free(entry.value_ptr.*);
    }
    store.map.deinit(store.gpa);
    store.* = undefined;
}

/// Stores a copy of `value` under `key`. On failure the store is unchanged.
pub fn put(store: *Store, io: Io, key: []const u8, value: []const u8) Allocator.Error!PutResult {
    const copy = try store.gpa.dupe(u8, value);
    errdefer store.gpa.free(copy);

    store.lock.lockUncancelable(io);
    defer store.lock.unlock(io);

    const gop = try store.map.getOrPut(store.gpa, key);
    if (gop.found_existing) {
        store.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = copy;
        return .replaced;
    }
    gop.key_ptr.* = store.gpa.dupe(u8, key) catch |err| {
        store.map.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = copy;
    return .created;
}

/// Returns a copy of the value stored under `key`, allocated with `allocator`,
/// or null if the key is absent.
pub fn get(store: *Store, io: Io, allocator: Allocator, key: []const u8) Allocator.Error!?[]u8 {
    store.lock.lockSharedUncancelable(io);
    defer store.lock.unlockShared(io);

    const value = store.map.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`. Returns true if it was present.
pub fn delete(store: *Store, io: Io, key: []const u8) bool {
    store.lock.lockUncancelable(io);
    defer store.lock.unlock(io);

    const kv = store.map.fetchRemove(key) orelse return false;
    store.gpa.free(kv.key);
    store.gpa.free(kv.value);
    return true;
}

/// Returns copies of every key, sorted ascending, allocated with `allocator`.
pub fn sortedKeys(store: *Store, io: Io, allocator: Allocator) Allocator.Error![]const []const u8 {
    const keys = blk: {
        store.lock.lockSharedUncancelable(io);
        defer store.lock.unlockShared(io);

        const keys = try allocator.alloc([]const u8, store.map.count());
        var it = store.map.keyIterator();
        for (keys) |*k| k.* = try allocator.dupe(u8, it.next().?.*);
        break :blk keys;
    };
    std.mem.sort([]const u8, keys, {}, lessThan);
    return keys;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

const testing = std.testing;

test "put, get, delete, list" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    try testing.expectEqual(PutResult.created, try store.put(io, "b", "2"));
    try testing.expectEqual(PutResult.created, try store.put(io, "a", "1"));
    try testing.expectEqual(PutResult.replaced, try store.put(io, "b", "two"));

    const value = (try store.get(io, testing.allocator, "b")).?;
    defer testing.allocator.free(value);
    try testing.expectEqualStrings("two", value);
    try testing.expectEqual(null, try store.get(io, testing.allocator, "zz"));

    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const keys = try store.sortedKeys(io, arena.allocator());
    try testing.expectEqual(@as(usize, 2), keys.len);
    try testing.expectEqualStrings("a", keys[0]);
    try testing.expectEqualStrings("b", keys[1]);

    try testing.expect(store.delete(io, "a"));
    try testing.expect(!store.delete(io, "a"));
}

//! Minimal HTTP/1.1 request-head parsing and response formatting.

const std = @import("std");
const ascii = std.ascii;
const mem = std.mem;
const Io = std.Io;

pub const Status = enum(u16) {
    @"continue" = 100,
    ok = 200,
    created = 201,
    no_content = 204,
    bad_request = 400,
    not_found = 404,
    method_not_allowed = 405,
    request_timeout = 408,
    content_too_large = 413,
    request_header_fields_too_large = 431,
    internal_server_error = 500,
    not_implemented = 501,
    service_unavailable = 503,
    http_version_not_supported = 505,

    pub fn phrase(status: Status) []const u8 {
        return switch (status) {
            .@"continue" => "Continue",
            .ok => "OK",
            .created => "Created",
            .no_content => "No Content",
            .bad_request => "Bad Request",
            .not_found => "Not Found",
            .method_not_allowed => "Method Not Allowed",
            .request_timeout => "Request Timeout",
            .content_too_large => "Content Too Large",
            .request_header_fields_too_large => "Request Header Fields Too Large",
            .internal_server_error => "Internal Server Error",
            .not_implemented => "Not Implemented",
            .service_unavailable => "Service Unavailable",
            .http_version_not_supported => "HTTP Version Not Supported",
        };
    }
};

/// A parsed request head. Slices point into the buffer given to `parseHead`.
pub const Request = struct {
    method: []const u8,
    target: []const u8,
    content_length: usize = 0,
    expect_continue: bool = false,
};

/// Reasons a request head is rejected, each mapped to a response status.
pub const ParseError = error{
    BadRequest,
    NotImplemented,
    VersionNotSupported,
};

pub fn statusForError(err: ParseError) Status {
    return switch (err) {
        error.BadRequest => .bad_request,
        error.NotImplemented => .not_implemented,
        error.VersionNotSupported => .http_version_not_supported,
    };
}

pub const continue_line = "HTTP/1.1 100 Continue\r\n\r\n";

/// Returns the length of the request head (through the blank line) if `buf`
/// contains a complete head, otherwise null. Accepts both CRLF CRLF and bare
/// LF LF terminators.
pub fn headLength(buf: []const u8) ?usize {
    var i: usize = 0;
    while (mem.indexOfScalarPos(u8, buf, i, '\n')) |nl| : (i = nl + 1) {
        const rest = buf[nl + 1 ..];
        if (mem.startsWith(u8, rest, "\n")) return nl + 2;
        if (mem.startsWith(u8, rest, "\r\n")) return nl + 3;
    }
    return null;
}

/// Parses a complete request head as delimited by `headLength`.
pub fn parseHead(head: []const u8) ParseError!Request {
    // Tolerate leading empty lines (RFC 9112 section 2.2).
    const start = mem.indexOfNone(u8, head, "\r\n") orelse return error.BadRequest;
    if (head[head.len - 1] != '\n') return error.BadRequest;
    // Every piece is one LF-terminated line, with the LF removed.
    var lines = mem.splitScalar(u8, head[start .. head.len - 1], '\n');

    var req = try parseRequestLine(lines.first());

    var have_length = false;
    while (lines.next()) |raw| {
        const line = trim(raw);
        if (line.len == 0) break; // end of head
        if (raw[0] == ' ' or raw[0] == '\t') return error.BadRequest; // obsolete line folding

        const colon = mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        const name = line[0..colon];
        if (name.len == 0 or !isToken(name)) return error.BadRequest;
        const value = trim(line[colon + 1 ..]);

        if (ascii.eqlIgnoreCase(name, "Content-Length")) {
            const n = parseLength(value) orelse return error.BadRequest;
            if (have_length and n != req.content_length) return error.BadRequest;
            req.content_length = n;
            have_length = true;
        } else if (ascii.eqlIgnoreCase(name, "Transfer-Encoding")) {
            if (!ascii.eqlIgnoreCase(value, "identity")) return error.NotImplemented;
        } else if (ascii.eqlIgnoreCase(name, "Expect")) {
            if (ascii.eqlIgnoreCase(value, "100-continue")) req.expect_continue = true;
        }
    }
    return req;
}

fn parseRequestLine(line: []const u8) ParseError!Request {
    const sp1 = mem.indexOfScalar(u8, line, ' ') orelse return error.BadRequest;
    const sp2 = mem.indexOfScalarPos(u8, line, sp1 + 1, ' ') orelse return error.BadRequest;
    const method = line[0..sp1];
    const target = line[sp1 + 1 .. sp2];
    const version = trim(line[sp2 + 1 ..]);

    if (method.len == 0 or target.len == 0 or !isToken(method)) return error.BadRequest;
    if (version.len != 8 or !mem.startsWith(u8, version, "HTTP/") or
        !ascii.isDigit(version[5]) or version[6] != '.' or !ascii.isDigit(version[7]))
        return error.BadRequest;
    if (version[5] != '1') return error.VersionNotSupported;
    return .{ .method = method, .target = target };
}

fn trim(s: []const u8) []const u8 {
    const start = mem.trimStart(u8, s, " \t");
    return mem.trimEnd(u8, start, " \t\r");
}

fn isTokenChar(c: u8) bool {
    return ascii.isAlphanumeric(c) or mem.indexOfScalar(u8, "!#$%&'*+-.^_`|~", c) != null;
}

fn isToken(s: []const u8) bool {
    for (s) |c| if (!isTokenChar(c)) return false;
    return true;
}

/// Parses a Content-Length value: one or more digits, no sign, no overflow.
fn parseLength(v: []const u8) ?usize {
    if (v.len == 0) return null;
    for (v) |c| if (!ascii.isDigit(c)) return null;
    return std.fmt.parseUnsigned(usize, v, 10) catch null;
}

/// Writes a complete response with `Connection: close`. A 204 carries neither
/// a body nor a Content-Length.
pub fn writeResponse(
    w: *Io.Writer,
    status: Status,
    content_type: ?[]const u8,
    body: []const u8,
) Io.Writer.Error!void {
    try w.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(status), status.phrase() });
    if (status == .no_content) {
        try w.writeAll("Connection: close\r\n\r\n");
        return;
    }
    if (content_type) |ct| try w.print("Content-Type: {s}\r\n", .{ct});
    try w.print("Content-Length: {d}\r\nConnection: close\r\n\r\n", .{body.len});
    try w.writeAll(body);
}

const testing = std.testing;

test headLength {
    try testing.expectEqual(null, headLength("GET / HTTP/1.1\r\nHost: x\r\n"));
    try testing.expectEqual(@as(?usize, 18), headLength("GET / HTTP/1.1\r\n\r\nbody"));
    try testing.expectEqual(@as(?usize, 16), headLength("GET / HTTP/1.1\n\nbody"));
}

test parseHead {
    const head = "PUT /kv/a HTTP/1.1\r\nContent-Length: 5\r\nexpect: 100-continue\r\n\r\n";
    const req = try parseHead(head);
    try testing.expectEqualStrings("PUT", req.method);
    try testing.expectEqualStrings("/kv/a", req.target);
    try testing.expectEqual(@as(usize, 5), req.content_length);
    try testing.expect(req.expect_continue);

    try testing.expectError(error.BadRequest, parseHead("GET /\r\n\r\n"));
    try testing.expectError(error.VersionNotSupported, parseHead("GET / HTTP/2.0\r\n\r\n"));
    try testing.expectError(error.NotImplemented, parseHead("GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseHead("GET / HTTP/1.1\r\n folded\r\n\r\n"));
    _ = try parseHead("\r\nGET / HTTP/1.1\r\nX: y\r\n\r\n");
}

test writeResponse {
    var buf: [256]u8 = undefined;
    var w: Io.Writer = .fixed(&buf);
    try writeResponse(&w, .ok, "text/plain", "ok");
    try testing.expectEqualStrings(
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok",
        w.buffered(),
    );
    w = .fixed(&buf);
    try writeResponse(&w, .no_content, null, "");
    try testing.expectEqualStrings("HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n", w.buffered());
}

//! kvhttp: an in-memory HTTP/1.1 key-value server. Usage: app <port>

const std = @import("std");
const net = std.Io.net;

const Server = @import("Server.zig");
const Store = @import("Store.zig");

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;

    var args = init.minimal.args.iterate();
    const argv0 = args.next() orelse "app";
    const port = blk: {
        const arg = args.next() orelse break :blk null;
        if (args.next() != null) break :blk null;
        break :blk parsePort(arg);
    } orelse {
        std.log.err("usage: {s} <port>", .{argv0});
        return 2;
    };

    ignoreSigpipe();
    // Every connection holds a descriptor; allow as many as the hard limit permits.
    std.process.raiseFileDescriptorLimit();

    var store: Store = .init(init.gpa);
    defer store.deinit();

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{ .reuse_address = true }) catch |err| {
        std.log.err("listen on 127.0.0.1:{d}: {t}", .{ port, err });
        return 1;
    };
    defer listener.deinit(io);

    var server: Server = .{ .io = io, .gpa = init.gpa, .store = &store, .options = .{} };
    server.serve(&listener) catch |err| {
        std.log.err("accept: {t}", .{err});
        return 1;
    };
    return 0;
}

fn parsePort(s: []const u8) ?u16 {
    const port = std.fmt.parseInt(u16, s, 10) catch return null;
    return if (port == 0) null else port;
}

/// Writes to a peer that has gone away must fail with an error, not kill the process.
fn ignoreSigpipe() void {
    const posix = std.posix;
    const act: posix.Sigaction = .{
        .handler = .{ .handler = posix.SIG.IGN },
        .mask = posix.sigemptyset(),
        .flags = 0,
    };
    posix.sigaction(.PIPE, &act, null);
}

test {
    _ = @import("http.zig");
    _ = @import("routes.zig");
    _ = @import("Store.zig");
}

test parsePort {
    try std.testing.expectEqual(@as(?u16, 8080), parsePort("8080"));
    try std.testing.expectEqual(null, parsePort("0"));
    try std.testing.expectEqual(null, parsePort("65536"));
    try std.testing.expectEqual(null, parsePort("-1"));
    try std.testing.expectEqual(null, parsePort("80x"));
}

//! Maps parsed HTTP requests onto key-value store operations.

const std = @import("std");
const mem = std.mem;
const Allocator = mem.Allocator;
const Io = std.Io;

const http = @import("http.zig");
const Store = @import("Store.zig");

pub const max_key_len = 64;
pub const max_value_len = 1024 * 1024;

pub const Response = struct {
    status: http.Status,
    content_type: ?[]const u8 = null,
    body: []const u8 = "",

    pub fn empty(status: http.Status) Response {
        return .{ .status = status };
    }
};

/// Handles one request. Response bytes are allocated with `arena`, which must
/// outlive the response.
pub fn handle(store: *Store, io: Io, arena: Allocator, req: http.Request, body: []const u8) Response {
    return route(store, io, arena, req, body) catch |err| switch (err) {
        error.OutOfMemory => .empty(.internal_server_error),
    };
}

fn route(store: *Store, io: Io, arena: Allocator, req: http.Request, body: []const u8) Allocator.Error!Response {
    const path = req.target;
    const method = Method.parse(req.method);

    if (mem.eql(u8, path, "/health")) {
        if (method != .GET) return .empty(.method_not_allowed);
        return .{ .status = .ok, .content_type = "text/plain", .body = "ok" };
    }
    if (mem.eql(u8, path, "/kv")) {
        if (method != .GET) return .empty(.method_not_allowed);
        return .{
            .status = .ok,
            .content_type = "application/json",
            .body = try keysJson(arena, try store.sortedKeys(io, arena)),
        };
    }
    if (mem.startsWith(u8, path, "/kv/")) {
        const key = path["/kv/".len..];
        if (!isValidKey(key)) return .empty(.bad_request);
        return switch (method) {
            .GET => if (try store.get(io, arena, key)) |value|
                .{ .status = .ok, .content_type = "application/octet-stream", .body = value }
            else
                .empty(.not_found),
            .PUT => switch (try store.put(io, key, body)) {
                .created => .empty(.created),
                .replaced => .empty(.ok),
            },
            .DELETE => .empty(if (store.delete(io, key)) .no_content else .not_found),
            .other => .empty(.method_not_allowed),
        };
    }
    return .empty(.not_found);
}

const Method = enum {
    GET,
    PUT,
    DELETE,
    other,

    fn parse(s: []const u8) Method {
        // Methods are case-sensitive (RFC 9110 section 9.1).
        return std.meta.stringToEnum(Method, s) orelse .other;
    }
};

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len < 1 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

/// Valid keys never need JSON escaping, so they are written verbatim.
fn keysJson(arena: Allocator, keys: []const []const u8) Allocator.Error![]u8 {
    var out: Io.Writer.Allocating = .init(arena);
    const w = &out.writer;
    w.writeByte('[') catch return error.OutOfMemory;
    for (keys, 0..) |key, i| {
        if (i != 0) w.writeByte(',') catch return error.OutOfMemory;
        w.print("\"{s}\"", .{key}) catch return error.OutOfMemory;
    }
    w.writeByte(']') catch return error.OutOfMemory;
    return out.toOwnedSlice();
}

const testing = std.testing;

test isValidKey {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("a/b"));
}

test handle {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();
    var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const Case = struct { []const u8, []const u8, []const u8, http.Status };
    const cases = [_]Case{
        .{ "GET", "/health", "", .ok },
        .{ "POST", "/health", "", .method_not_allowed },
        .{ "PUT", "/kv/b", "2", .created },
        .{ "PUT", "/kv/a", "1", .created },
        .{ "PUT", "/kv/a", "one", .ok },
        .{ "GET", "/kv/a", "", .ok },
        .{ "PATCH", "/kv/a", "", .method_not_allowed },
        .{ "GET", "/kv/", "", .bad_request },
        .{ "GET", "/kv/a/b", "", .bad_request },
        .{ "GET", "/nope", "", .not_found },
        .{ "POST", "/kv", "", .method_not_allowed },
        .{ "DELETE", "/kv/b", "", .no_content },
        .{ "DELETE", "/kv/b", "", .not_found },
        .{ "GET", "/kv/b", "", .not_found },
    };
    for (cases) |c| {
        const res = handle(&store, io, arena, .{ .method = c[0], .target = c[1] }, c[2]);
        try testing.expectEqual(c[3], res.status);
    }

    _ = try store.put(io, "c", "3");
    const list = handle(&store, io, arena, .{ .method = "GET", .target = "/kv" }, "");
    try testing.expectEqualStrings("[\"a\",\"c\"]", list.body);
    const get = handle(&store, io, arena, .{ .method = "GET", .target = "/kv/a" }, "");
    try testing.expectEqualStrings("one", get.body);
}
